import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"設定矛盾自己チェック表","description":"","frontmatter":{},"headers":[],"relativePath":"ja/97-设定矛盾自查表.md","filePath":"ja/97-设定矛盾自查表.md","lastUpdated":null}'),h={name:"ja/97-设定矛盾自查表.md"};function l(o,t,i,n,b,s){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="設定矛盾自己チェック表" tabindex="-1">設定矛盾自己チェック表 <a class="header-anchor" href="#設定矛盾自己チェック表" aria-label="Permalink to &quot;設定矛盾自己チェック表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>97</td></tr><tr><td>所属モジュール</td><td>付録と参考資料</td></tr><tr><td>キーワード</td><td>矛盾自己チェック、設定一貫性、論理検証、品質管理、設定保守</td></tr></tbody></table><h2 id="_1-説明" tabindex="-1">1. 説明 <a class="header-anchor" href="#_1-説明" aria-label="Permalink to &quot;1. 説明&quot;">​</a></h2><p>設定矛盾自己チェック表は、アンカー共生文明設定体系の品質管理ツールであり、新規設定の創作、旧設定の改訂、文書更新の際に、存在する可能性のある設定矛盾と論理的不一致を体系的に洗い出すために使用される。本自己チェック表は、SPEC.mdで確立された14の核心設定と一貫性チェックリストに基づいて作成されており、世界観、修練体系、社会制度、法律体系、生命形態、技術体系、歴史紀元、位面間交流など、すべてのモジュールをカバーしている。いかなる新規設定または改訂内容も、正式に設定体系に組み込まれる前に、本自己チェック表のすべてのチェック項目を通過しなければならない。</p><h2 id="_2-核心設定一貫性チェック" tabindex="-1">2. 核心設定一貫性チェック <a class="header-anchor" href="#_2-核心設定一貫性チェック" aria-label="Permalink to &quot;2. 核心設定一貫性チェック&quot;">​</a></h2><h3 id="_2-1-宇宙名称と基本概念" tabindex="-1">2.1 宇宙名称と基本概念 <a class="header-anchor" href="#_2-1-宇宙名称と基本概念" aria-label="Permalink to &quot;2.1 宇宙名称と基本概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>チェック項目</th><th>チェック内容</th><th>合格基準</th><th>よくある問題</th></tr></thead><tbody><tr><td>C01</td><td>宇宙名称が統一されているか</td><td>全文で「万霊衡锚本源宙」または略称「衡元宙」を統一的に使用し、他の名称を使用しない</td><td>「宇宙」「万界」「諸天」などの非標準名称の混用</td></tr><tr><td>C02</td><td>アンカーの定義が一致しているか</td><td>アンカーは常に「法則ネットワーク内の安定ノード」と定義され、その本質的属性を変更しない</td><td>アンカーを物品、生物、またはエネルギー体として記述する</td></tr><tr><td>C03</td><td>共生の理念が統一されているか</td><td>共生は常に「異なる生命間の互恵協力による共同進化」を意味し、反略奪の立場から逸脱しない</td><td>共生を同化、呑み込み、または制御として記述する</td></tr><tr><td>C04</td><td>核心的立場が一致しているか</td><td>常に「現実を基とする」原則を堅持し、虚構設定を現実として記述しない</td><td>虚構と現実の境界を混同する</td></tr></tbody></table><h3 id="_2-2-修練体系の一貫性" tabindex="-1">2.2 修練体系の一貫性 <a class="header-anchor" href="#_2-2-修練体系の一貫性" aria-label="Permalink to &quot;2.2 修練体系の一貫性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>チェック項目</th><th>チェック内容</th><th>合格基準</th><th>よくある問題</th></tr></thead><tbody><tr><td>C05</td><td>体系の総数が一致しているか</td><td>本源修練体系の総数は常に三百套であり、増減しない</td><td>「三百余套」「数百套」などのあいまいな表現の出現</td></tr><tr><td>C06</td><td>体系の分類が一致しているか</td><td>常に六大類（本源推演、生命循環、空間法理、意識昇維、共生ネットワーク、応用工程）に分類し、各類五十套とする</td><td>他の分類方式の出現または類別数の不一致</td></tr><tr><td>C07</td><td>本源三基が一致しているか</td><td>前三套は常に推演迭代（001）、生命循環（002）、空間法理調度（003）とする</td><td>前三套の番号または名称を変更する</td></tr><tr><td>C08</td><td>倍增果実の設定が一致しているか</td><td>倍增果実は常に「開局バフ」であり、百倍推演増幅を提供し、すでに技術化応用されている</td><td>倍增果実を天然果実または未技術化として記述する</td></tr><tr><td>C09</td><td>修練境界が一致しているか</td><td>各体系の境界区分は文書14『修練境界統一区分』と一致する</td><td>統一区分と矛盾する境界名称を独自に考案する</td></tr><tr><td>C10</td><td>反略奪の立場が一致しているか</td><td>略奪式修練を肯定的または受け入れ可能な体系として記述しない</td><td>略奪式修練を弁護または美化する</td></tr></tbody></table><h3 id="_2-3-社会と法律の一貫性" tabindex="-1">2.3 社会と法律の一貫性 <a class="header-anchor" href="#_2-3-社会と法律の一貫性" aria-label="Permalink to &quot;2.3 社会と法律の一貫性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>チェック項目</th><th>チェック内容</th><th>合格基準</th><th>よくある問題</th></tr></thead><tbody><tr><td>C11</td><td>文明分型が一致しているか</td><td>常に五种分型（東アジア集約、北欧福利、北米多元、欧州大陸社会、発展中追趕）とする</td><td>第六種分型の出現または分型名称の変更</td></tr><tr><td>C12</td><td>法律体系が一致しているか</td><td>常に憲法＋労働法＋消費者保護法＋五部配套法（教育、医療、住宅、環境、独占禁止）とする</td><td>一部の法律を漏らすか、未設定の法律を追加する</td></tr><tr><td>C13</td><td>治理アーキテクチャが一致しているか</td><td>常にアンカー議事会（立法）＋共生執行委員会（行政）＋共生法院（司法）＋アンカー監督委員会（監督）とする</td><td>機関名称または権力分配を変更する</td></tr><tr><td>C14</td><td>聯産承包メカニズムが一致しているか</td><td>常に「多労多得」を核心とし、資源分配は貢献に基づく</td><td>聯産承包を平均主義または按需分配として記述する</td></tr><tr><td>C15</td><td>20%活性化戦略が一致しているか</td><td>常に前期に20%の衆生を位面至高強者として活性化する</td><td>活性化の割合または目標を変更する</td></tr></tbody></table><h2 id="_3-クロスモジュール論理一貫性チェック" tabindex="-1">3. クロスモジュール論理一貫性チェック <a class="header-anchor" href="#_3-クロスモジュール論理一貫性チェック" aria-label="Permalink to &quot;3. クロスモジュール論理一貫性チェック&quot;">​</a></h2><h3 id="_3-1-タイムラインの一貫性" tabindex="-1">3.1 タイムラインの一貫性 <a class="header-anchor" href="#_3-1-タイムラインの一貫性" aria-label="Permalink to &quot;3.1 タイムラインの一貫性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>チェック項目</th><th>チェック内容</th><th>合格基準</th><th>よくある問題</th></tr></thead><tbody><tr><td>L01</td><td>歴史事件の時間が一致しているか</td><td>すべての歴史事件の時間は文書93『編年史簡表』および文書70-79と一致する</td><td>同一事件が異なる文書で時間が不一致</td></tr><tr><td>L02</td><td>紀元区分が一致しているか</td><td>紀元名称と起止時間は文書70『紀元区分総表』と一致する</td><td>未設定の紀元の出現または紀元境界の変更</td></tr><tr><td>L03</td><td>人物の時期が一致しているか</td><td>重要人物の活躍時期は文書95『重要人物と組織』と一致する</td><td>人物がその存在しない時代に出現する</td></tr><tr><td>L04</td><td>技術の出現時間が一致しているか</td><td>各技術の発明と成熟時間は編年史と一致する</td><td>ある技術がその発明前の時代で使用される</td></tr></tbody></table><h3 id="_3-2-技術体系の一貫性" tabindex="-1">3.2 技術体系の一貫性 <a class="header-anchor" href="#_3-2-技術体系の一貫性" aria-label="Permalink to &quot;3.2 技術体系の一貫性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>チェック項目</th><th>チェック内容</th><th>合格基準</th><th>よくある問題</th></tr></thead><tbody><tr><td>T01</td><td>複製鏡技術が一致しているか</td><td>複製鏡は常に「原物に接触しない1:1複製装置」であり、複製過程はゼロ干渉</td><td>複製鏡を原物を変更可能または原物に接触する必要があるとして記述する</td></tr><tr><td>T02</td><td>隔離空間が一致しているか</td><td>隔離空間は常に「外部と法則障壁によって完全に隔離された独立空間」である</td><td>隔離空間を普通の部屋または仮想空間として記述する</td></tr><tr><td>T03</td><td>空間法理修為の要件が一致しているか</td><td>各空間技術の修為要件は文書13『空間法理調度体系詳解』と一致する</td><td>低修為者が高修為を必要とする技術を使用する</td></tr><tr><td>T04</td><td>エネルギー単位が一致しているか</td><td>エネルギー計量は統一的に「標準エネルギー単位」を使用し、他の単位を使用しない</td><td>「霊石」「晶幣」などの非標準エネルギー単位の混用</td></tr></tbody></table><h3 id="_3-3-位面間と時間ルールの一貫性" tabindex="-1">3.3 位面間と時間ルールの一貫性 <a class="header-anchor" href="#_3-3-位面間と時間ルールの一貫性" aria-label="Permalink to &quot;3.3 位面間と時間ルールの一貫性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>チェック項目</th><th>チェック内容</th><th>合格基準</th><th>よくある問題</th></tr></thead><tbody><tr><td>K01</td><td>「先観測後有限干渉」が一致しているか</td><td>すべての時間回溯と位面間操作はこの原則に従わなければならず、観測段階をスキップしてはならない</td><td>観測なしで直接干渉する操作を記述する</td></tr><tr><td>K02</td><td>「僅回伝知識」が一致しているか</td><td>考古産出は抽象的な知識と情報に限られ、物質、エネルギー、または生命体を回伝してはならない</td><td>文物またはサンプルを本位面に持ち帰る行為を記述する</td></tr><tr><td>K03</td><td>穿梭許可制度が一致しているか</td><td>すべての位面穿梭は相応等級の許可を取得しなければならず、無許可で穿梭してはならない</td><td>無許可の勝手な穿梭を記述する</td></tr><tr><td>K04</td><td>時間悖論の分類が一致しているか</td><td>悖論は常に弑祖、情報、本体、事件の四類に分類され、増減または変更してはならない</td><td>未設定の悖論タイプの出現</td></tr><tr><td>K05</td><td>位面分類が一致しているか</td><td>位面は常に五大類（物質本位、エネルギー顕化、意識主導、法則破碎、本源近隣）に分類される</td><td>他の分類方式の出現</td></tr></tbody></table><h3 id="_3-4-生命と種族の一貫性" tabindex="-1">3.4 生命と種族の一貫性 <a class="header-anchor" href="#_3-4-生命と種族の一貫性" aria-label="Permalink to &quot;3.4 生命と種族の一貫性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>チェック項目</th><th>チェック内容</th><th>合格基準</th><th>よくある問題</th></tr></thead><tbody><tr><td>S01</td><td>種族分類が一致しているか</td><td>種族は常に八大類（人形態、獣形態、植物形態、元素形態、エネルギー形態、意識形態、機械形態、混合形態）に分類される</td><td>他の分類方式の出現</td></tr><tr><td>S02</td><td>奇特生命の処置が一致しているか</td><td>奇特生命は常に三類の標準化処置フローに従って処理される</td><td>フローなしの勝手な処置を記述する</td></tr><tr><td>S03</td><td>暗黒置換体の処置が一致しているか</td><td>暗黒置換体は常に双魂倫理と四類分支の処置ルールに従って処理される</td><td>一方の魂を簡単に消滅させる行為を記述する</td></tr><tr><td>S04</td><td>万族平等が一致しているか</td><td>すべての智慧種族は法律の前で一律に平等であり、種族差別の設定があってはならない</td><td>ある種族を生まれつき劣等または奴隷化されるべきとして記述する</td></tr></tbody></table><h2 id="_4-文書フォーマットと規範チェック" tabindex="-1">4. 文書フォーマットと規範チェック <a class="header-anchor" href="#_4-文書フォーマットと規範チェック" aria-label="Permalink to &quot;4. 文書フォーマットと規範チェック&quot;">​</a></h2><table tabindex="0"><thead><tr><th>チェック項目</th><th>チェック内容</th><th>合格基準</th><th>よくある問題</th></tr></thead><tbody><tr><td>F01</td><td>ファイル名のフォーマットが正しいか</td><td>ファイル名のフォーマットは「XX-文書タイトル.md」であり、XXは2桁の数字番号</td><td>番号の欠落、タイトルにスペース、ファイル拡張子の誤り</td></tr><tr><td>F02</td><td>文書情報ブロックが完全か</td><td>先頭に番号、所属モジュール、キーワード（3-5個）を含む情報テーブルがある</td><td>情報ブロックの欠落またはフィールドの不完全</td></tr><tr><td>F03</td><td>二级タイトルの数が基準を満たしているか</td><td>本文には少なくとも3つの二级タイトルの章が含まれる</td><td>二级タイトルが3つ未満</td></tr><tr><td>F04</td><td>構造化要素が使用されているか</td><td>可読性を高めるためにリスト、テーブルなどの構造化要素を使用する</td><td>プレーンテキストの段落のみで、リストまたはテーブルがない</td></tr><tr><td>F05</td><td>結語が存在するか</td><td>末尾に「結語」の段落がある</td><td>結語の欠落</td></tr><tr><td>F06</td><td>関連文書が存在するか</td><td>末尾に2-3部の関連文書の番号と名称をリストアップする</td><td>関連文書の欠落または関連文書が存在しない</td></tr><tr><td>F07</td><td>文字数が基準を満たしているか</td><td>本文は800字以上（タイトルとメタ情報を除く）</td><td>本文が800字未満</td></tr><tr><td>F08</td><td>用語の使用が統一されているか</td><td>「衡元宙」「アンカー」「共生」などの標準用語を使用する</td><td>用語が不統一または非標準表現の使用</td></tr><tr><td>F09</td><td>執筆スタイルが適切か</td><td>厳粛で体系的な設定文書のスタイルであり、口語的表現がない</td><td>口語的、勝手な表現の出現</td></tr><tr><td>F10</td><td>番号がリストと一致しているか</td><td>文書番号とタイトルはSPEC.mdの100部の文書完全リストと一致する</td><td>番号またはタイトルがリストと一致しない</td></tr></tbody></table><h2 id="_5-自己チェックフローと使用方法" tabindex="-1">5. 自己チェックフローと使用方法 <a class="header-anchor" href="#_5-自己チェックフローと使用方法" aria-label="Permalink to &quot;5. 自己チェックフローと使用方法&quot;">​</a></h2><h3 id="_5-1-新規設定創作の自己チェックフロー" tabindex="-1">5.1 新規設定創作の自己チェックフロー <a class="header-anchor" href="#_5-1-新規設定創作の自己チェックフロー" aria-label="Permalink to &quot;5.1 新規設定創作の自己チェックフロー&quot;">​</a></h3><ol><li><strong>予備自己チェック</strong>: 創作完成後、創作者は本自己チェック表に照らして項目ごとにチェックし、問題のある項目をマークする。</li><li><strong>改訂完善</strong>: マークされた問題項目を改訂し、すべて合格することを確認する。</li><li><strong>クロス審査</strong>: 別の設定創作者に提出してクロス審査を行い、特にクロスモジュールの一貫性を重点的にチェックする。</li><li><strong>委員会審定</strong>: 重大な設定変更は設定保守委員会に提出して審定を受けなければならない。</li><li><strong>アーカイブ更新</strong>: すべてのチェックに合格した後、正式に設定体系に組み込まれ、関連するインデックス文書を更新する。</li></ol><h3 id="_5-2-旧設定改訂の自己チェックフロー" tabindex="-1">5.2 旧設定改訂の自己チェックフロー <a class="header-anchor" href="#_5-2-旧設定改訂の自己チェックフロー" aria-label="Permalink to &quot;5.2 旧設定改訂の自己チェックフロー&quot;">​</a></h3><ol><li><strong>影響評価</strong>: 改訂内容が影響を与える可能性のある他の文書と設定モジュールを評価する。</li><li><strong>関連チェック</strong>: 影響を受けるすべての関連文書に対して一貫性チェックを行う。</li><li><strong>同期改訂</strong>: 関連文書内の影響を受ける内容に対して同期改訂を行う。</li><li><strong>バージョン記録</strong>: 文書99『文書バージョンと保守説明』に改訂内容とバージョン番号を記録する。</li><li><strong>公告通知</strong>: 重大な改訂はすべての設定使用者に変更公告を発布しなければならない。</li></ol><h3 id="_5-3-定期全面自己チェック" tabindex="-1">5.3 定期全面自己チェック <a class="header-anchor" href="#_5-3-定期全面自己チェック" aria-label="Permalink to &quot;5.3 定期全面自己チェック&quot;">​</a></h3><p>設定保守委員会は四半期ごとに1回の全面的な設定一貫性自己チェックを実施し、全部で100部の文書に対して体系的なチェックを行い、潜在的な設定矛盾と論理的不一致を洗い出す。自己チェックの結果は『四半期設定一貫性報告』としてまとめられ、すべての設定使用者に公開される。</p><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>設定矛盾自己チェック表は、アンカー共生文明設定体系の「品質憲法」である。体系的でリスト化されたチェック項目を通じて、設定体系が不断の拡張と改訂の過程で常に論理的自己一貫性と用語の統一性を維持することを保証する。巨大な設定体系が最も恐れるのは内容が十分に豊かでないことではなく、内部矛盾が丛生し前後不一致になることである。本自己チェック表の存在は、アンカー共生文明設定体系が開放性と成長性を維持しつつ、常に堅実な一貫性の根基を持つようにするためである。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>99-文書バージョンと保守説明</li><li>90-術語詞典</li><li>00-衡元宙宇宙総覧</li></ul>',33)])])}const u=d(h,[["render",l]]);export{c as __pageData,u as default};
